import{_ as i,a0 as a,w as s,s as l,ao as c,I as p,x as o,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Linux cp 命令的15个示例 - 创建文件和目录的副本 | LCTT x X-CMD","titleTemplate":false,"description":"Linux cp 命令的15个示例 - 创建文件和目录的副本 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux cp 命令的15个示例 - 创建文件和目录的副本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux cp 命令的15个示例 - 创建文件和目录的副本 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/15 Linux cp Command Examples - Create a Copy of Files and Directories","title":"Linux cp 命令的15个示例 - 创建文件和目录的副本","tag":"201403","desc":""},"relativePath":"201403/15 Linux cp Command Examples - Create a Copy of Files and Directories.md","filePath":"[post].md"}'),g={name:"201403/15 Linux cp Command Examples - Create a Copy of Files and Directories.md"};function d(m,t,h,f,u,_){const e=a("Link");return s(),l("div",null,[t[11]||(t[11]=c(`<h1 id="linux-cp-命令的15个示例-创建文件和目录的副本" tabindex="-1">Linux cp 命令的15个示例 - 创建文件和目录的副本 <a class="header-anchor" href="#linux-cp-命令的15个示例-创建文件和目录的副本" aria-label="Permalink to “Linux cp 命令的15个示例 - 创建文件和目录的副本”">​</a></h1><p>拷贝文件和目录是每一个操作系统的基本指令。备份行为基本上是创建文件和目录的副本。在Linux系统下，我们可以用<strong>cp</strong>命令来实现。</p><h3 id="copy-命令是什么" tabindex="-1">copy 命令是什么 <a class="header-anchor" href="#copy-命令是什么" aria-label="Permalink to “copy 命令是什么”">​</a></h3><p>正如我们在上文提到的，<strong>cp</strong>是一个用来创建文件和目录副本的命令。在这里我们提供了一些在日常操作中可能用到的cp命令的实例。</p><h3 id="_1-不带任何参数下-运行cp" tabindex="-1">1. 不带任何参数下，运行cp <a class="header-anchor" href="#_1-不带任何参数下-运行cp" aria-label="Permalink to “1. 不带任何参数下，运行cp”">​</a></h3><p>这是 cp 命令最基础的使用。 拷贝名为 myfile.txt 从一个位置到另一个位置，我们可以像这样子输入：</p><pre><code>$ cp myfile.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_default.png" alt="Copy without options"></p><p>如果我们没有输入绝对路径，这意味着我们正在当前目录下拷贝一个文件。在上面的实例中，<strong>myfile.txt</strong>位于<strong>/home/pungki/Documents</strong>目录下。如果我们当前目录正是<strong>/home/pungki/Documets</strong>,那么没有必要输入<strong>/home/pungki/Documents/myfile.txt</strong>来拷贝文件。当<strong>/home/pungki/office</strong>是一个目录，则文件会拷贝到里面。</p><h4 id="_2-同时拷贝多个文件" tabindex="-1">2. 同时拷贝多个文件 <a class="header-anchor" href="#_2-同时拷贝多个文件" aria-label="Permalink to “2. 同时拷贝多个文件”">​</a></h4><p>要在同时拷贝多个文件，我们只需要将多个文件用空格隔开。如下示例：</p><pre><code>$ cp file_1.txt file_2.txt file_3.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_multiple_file.png" alt="Copying multiple files"></p><h4 id="_3-拷贝一个目录" tabindex="-1">3. 拷贝一个目录 <a class="header-anchor" href="#_3-拷贝一个目录" aria-label="Permalink to “3. 拷贝一个目录”">​</a></h4><p>要拷贝一个目录的话会有点棘手。你需要添加 <strong>-r</strong> 或者 <strong>-R</strong> 选项来实现。<strong>-r</strong>或<strong>-R</strong> 选项表明递归操作。无论该目录是否为空目录，<strong>这个选项都是必要的</strong>。如下示例：</p><pre><code>$ cp -r directory_1 /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_directory.png" alt="Copy directory"></p><p>需要注意的一件事，你需要<strong>移除在目录名尾部的斜杠</strong>。否则你会收到类似的错误信息<strong>cp: omitting directory‘directory_1/</strong>’</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_directory_error.png" alt="Copy directory error"></p><p>如果你收到错误信息，则目录不会被拷贝到目标文件夹。</p><h4 id="_4-创建文件的硬链接-而不是拷贝它们" tabindex="-1">4. 创建文件的硬链接，而不是拷贝它们#### <a class="header-anchor" href="#_4-创建文件的硬链接-而不是拷贝它们" aria-label="Permalink to “4. 创建文件的硬链接，而不是拷贝它们####”">​</a></h4><p>拷贝文件意味着你必须使用一些存储空间来储存拷贝的文件。有时候出于某种原因，你可能想要创建“快捷方式”或者链接到文件，而不是拷贝它们。要做到这一点，我们可以使用<strong>-l</strong>选项。</p><pre><code>$ cp -l file_4.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks.png" alt="Copy hardlinks"></p><p>从上图看出，我们看到<strong>file_4.txt</strong>的硬链接已经拷贝到<strong>/home/pungki/office/file_4.txt</strong>。标记有同样的 inode, <strong>835386</strong>。但是请注意，硬链接不能用来创建目录。下面让我们看一个例子。</p><p><em>原目录 directory_1 的 inode 值是 278230</em><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks_dir_1_ori.png" alt="Inode number of original directory"></p><p><em>原文件 file_5.txt 的 inode 值是 279231</em><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks_file_5_ori.png" alt="Original inode number of file"></p><p><em>对 directory_1 执行 cp 命令</em><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks_rl_dir.png" alt="Copy using -rl options"></p><p><em>拷贝的 directory_1副本的 inode 值是 274800</em><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks_dir_1_result.png" alt="Inode number of copied directory"></p><p><em>拷贝的 file_5.txt副本的 inode 值是 279231。跟它的原文件一样</em><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_hardlinks_file_5_result.png" alt="Inode number of copied file"></p><h4 id="_5-创建文件的符号链接" tabindex="-1">5. 创建文件的符号链接 <a class="header-anchor" href="#_5-创建文件的符号链接" aria-label="Permalink to “5. 创建文件的符号链接”">​</a></h4><p>也有一种链接叫做 <strong>软链接</strong> 或 <strong>符号链接</strong>。我们用 <strong>-s</strong> 选项来实现。下面是命令的示例。</p><pre><code>$ cp -s /home/pungki/Documents/file_6.txt file_6.txt
</code></pre><p>创建符号链接只能在当前目录下进行。在上面的截图中，我们想要创建符号链接 <strong>/home/pungki/office/file_6.txt 指向原文件 /home/pungki/Documents/file_6.txt</strong>。但是为了创建符号链接，<strong>我必须</strong>在将/home/pungki/office作为目标目录。一旦我设法进入目录，我就可以向上面一样运行 cp <strong>-s</strong> 命令。</p><p>现在你列出文件详情，你会看到<strong>/home/pungki/office/file_6.txt</strong>指向了原文件。在其文件名后标记了箭头符号。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_symlinks.png" alt="Symbolic links"></p><h4 id="_6-不随符号链接拷贝原文件" tabindex="-1">6. 不随符号链接拷贝原文件 <a class="header-anchor" href="#_6-不随符号链接拷贝原文件" aria-label="Permalink to “6. 不随符号链接拷贝原文件”">​</a></h4><p>[译注:意思是只拷贝符号链接文件]</p><p>我们可以用 <strong>-P</strong> 选项来实现。当对符号链接使用 cp 命令，它会照原样拷贝它自身。来看看下面的示例。</p><pre><code>$ cp -P file_6.txt ./movie
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_P.png" alt="Copy using -P option"></p><p>如你所见，cp 命令照原样拷贝<strong>file_6.txt</strong>自身。文件类型仍然是一个符号链接。</p><h4 id="_7-随符号链接拷贝原文件" tabindex="-1">7. 随符号链接拷贝原文件 <a class="header-anchor" href="#_7-随符号链接拷贝原文件" aria-label="Permalink to “7. 随符号链接拷贝原文件”">​</a></h4><p>现在我们可以试一下<strong>-L</strong>选项。基本上，这个刚好与上面的 -P 选项 <strong>相反</strong>。下面是个示例：</p><pre><code>$ cp -L file_6.txt ./movie
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_L.png" alt="Copy using -L option"></p><p>使用这个选项，拷贝的文件将会和<strong>file_6.txt</strong>原文件一样。我们可以从文件大小看出来。拷贝的文件有<strong>50 字节</strong>而当<strong>file_6.txt</strong>作为符号链接时文件大小只有<strong>33 字节</strong>。</p><h4 id="_8-文件归档" tabindex="-1">8. 文件归档 <a class="header-anchor" href="#_8-文件归档" aria-label="Permalink to “8. 文件归档”">​</a></h4><p>当我们去拷贝一个目录时，我们会用<strong>-r</strong>或者<strong>-R</strong>选项。但是我们也可以用<strong>-a</strong>选项来归档文件。这样会创建文件和目录的<strong>准确套录</strong>，如果有的话也可以包括符号链接。下面是示例：[译注：-a 会保留原文件或目录的属性]</p><pre><code>$ cp -a directory_1/ /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_a.png" alt="Copy using -a option"></p><p>上列的命令会拷贝一个名为 directory_1 的目录到<strong>/home/pungki/office</strong>目录下。如你所见，<strong>file_6.txt</strong>依然作为符号链接被复制。</p><h4 id="_9-显示正在做什么" tabindex="-1">9. 显示正在做什么 <a class="header-anchor" href="#_9-显示正在做什么" aria-label="Permalink to “9. 显示正在做什么”">​</a></h4><p>默认情况下，当拷贝作业成功时，我们仅仅会再次看到命令提示符。如果你想了解在拷贝文件时都发生了什么，我们可以用 <strong>-v</strong> 选项。</p><pre><code>$ cp -v *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_v.png" alt="Verbose option"></p><p>当我们从当前目录下拷贝所有的 txt 文件到 <strong>/home/pungki/office</strong> 目录，<strong>-v</strong>选项会显示正在操作的过程。这些额外的信息会帮助我们了解更多拷贝过程。</p><h4 id="_10-当原文件较目标文件新时拷贝" tabindex="-1">10. 当原文件较目标文件新时拷贝 <a class="header-anchor" href="#_10-当原文件较目标文件新时拷贝" aria-label="Permalink to “10. 当原文件较目标文件新时拷贝”">​</a></h4><p>我们用 <strong>-u</strong>选项来实现。下面是具体示例:</p><pre><code>$ cp -vu *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_u.png" alt="Copy only if newer"></p><p>起初我们看到<strong>file_1.txt 是0字节</strong>大小。然后我们用 vi 编辑，加入一些内容并保存。接下来，我们发现文件大小已经变为了 36 个字节。 与此同时在<strong>/home/pungki/office</strong>目录中，我们<strong>已经包含了所有</strong>txt文件。当我们用 -u 选项，结合 -v 选项来查看具体操作，cp 命令会只拷贝比目标目录下新的文件。因此，我们看到<strong>只有 file_1.txt 拷贝到 /home/pungki/office 目录下</strong>。</p><h4 id="_11-使用交互模式" tabindex="-1">11. 使用交互模式 <a class="header-anchor" href="#_11-使用交互模式" aria-label="Permalink to “11. 使用交互模式”">​</a></h4><p>交互模式下会询问是否覆盖目标目录下的文件。使用 <strong>-i</strong> 选项，启用交互模式。</p><pre><code>$ cp -ir directory_1/ /home/pungki/office/
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_i.png" alt="Interactive mode"></p><h4 id="_12-创建备份文件" tabindex="-1">12. 创建备份文件 <a class="header-anchor" href="#_12-创建备份文件" aria-label="Permalink to “12. 创建备份文件”">​</a></h4><p>当目标目录已经含有同名文件，默认情况下 cp 命令会覆盖目标目录下的同名文件。使用 <strong>--backup</strong> 选项，cp 命令会为每一个现有的目标文件做一个备份。../office 相对于 /home/pungki/office 。下面是示例：</p><pre><code>$ cp --backup=simple -v *.txt ../office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_backup.png" alt="Backup option"></p><p>正如我们看到的，<strong>--backup=simple</strong> 选项会创建一个在文件名末尾用波浪符标记(~)的备份文件。<strong>--backup</strong> 选项也有一些其他控制：</p><ul><li><strong>none, off</strong>:从不备份(即使给出 --backup)</li><li><strong>numbered, t</strong>:用编号备份</li><li><strong>existing, nil</strong> :如果编号备份存在则使用编号备份，否者用简易备份[译注：也就是用波浪号]</li><li><strong>simple, never</strong> :总是使用简易备份</li></ul><h4 id="_13-只拷贝文件属性" tabindex="-1">13. 只拷贝文件属性 <a class="header-anchor" href="#_13-只拷贝文件属性" aria-label="Permalink to “13. 只拷贝文件属性”">​</a></h4><p>cp 命令也提供给我们 <strong>--attributes-only</strong> 选项。顾名思义，这个选项只会拷贝文件名及其属性，不会拷贝任何数据。下面是示例：</p><pre><code>$ cp --attributes-only file_6.txt -v ../office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_attributes_only.png" alt="Copy attributes only"></p><p>从上图看出， <strong>原文件 file_6.txt 有 50 字节</strong>大小。用了 <strong>--attributes-only</strong>选项，<strong>拷贝的文件只有0字节</strong>大小。这是因为文件内容并没有拷贝。</p><h3 id="_14-强制拷贝" tabindex="-1">14. 强制拷贝 <a class="header-anchor" href="#_14-强制拷贝" aria-label="Permalink to “14. 强制拷贝”">​</a></h3><p>用了 <strong>-f</strong> 选项会强制进行拷贝操作。如果目标文件不能打开，可以用 <strong>-f</strong> 尝试一下。</p><pre><code>$ cp -f *.txt -v ../office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_f.png" alt="Copy with force"></p><h4 id="_15-在拷贝之前先删除目标" tabindex="-1">15. 在拷贝之前先删除目标 <a class="header-anchor" href="#_15-在拷贝之前先删除目标" aria-label="Permalink to “15. 在拷贝之前先删除目标”">​</a></h4><p>我们可以用，<strong>--remove-destination 选项</strong> 实现。这个选项与上面的<strong>-f选项形成对照</strong>。如果 cp 命令在目标目录下发现同名文件， cp 命令会先删除目标文件，然后再拷贝一份新的。下面是示例：</p><pre><code>$ cp --remove-destination *.txt -v ../office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/cp_remove_destination.png" alt="Remove destination option"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>cp 命令是 Linux 下最基础的命令之一。对于那些想要学习 Linux 的人，必须得把这个命令掌握。当然你也可以在你的终端下键入 <strong>man cp</strong> 或者 <strong>cp --help</strong> 来显示更多帮助信息。</p><hr>`,88)),p("p",null,[t[1]||(t[1]=o("via: ",-1)),n(e,{href:"http://linoxide.com/linux-command/linux-cp-command/"},{default:r(()=>[...t[0]||(t[0]=[o("http://linoxide.com/linux-command/linux-cp-command/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=o("译者：",-1)),n(e,{href:"https://github.com/Luoxcat"},{default:r(()=>[...t[2]||(t[2]=[o("Luoxcat",-1)])]),_:1}),t[5]||(t[5]=o(" 校对：",-1)),n(e,{href:"http://blog.csdn.net/tinyeyeser"},{default:r(()=>[...t[3]||(t[3]=[o("Mr小眼儿",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/"},{default:r(()=>[...t[7]||(t[7]=[o("Linux中国",-1)])]),_:1}),t[10]||(t[10]=o(" 荣誉推出",-1))])])}const y=i(g,[["render",d]]);export{b as __pageData,y as default};
